diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..ee4932d
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,56 @@
+import { AppError } from "../errors.js";
+import { memoryStore } from "../db/store.js";
+import { consume } from "../domain/batches.js";
+import { scaled } from "../domain/recipes.js";
+import { t } from "../i18n/messages.js";
+import { parseCsv } from "./csv.js";
+
+/** Imports a whole CSV file atomically and returns imported ticket and dish counts. */
+export function importSales(store, text) {
+  const lines = text.split(/\r?\n/).filter((line) => line.trim());
+  for (const [index, line] of lines.entries()) {
+    if (!/^(?:"(?:[^"]|"")*"|[^",]*)(?:,(?:"(?:[^"]|"")*"|[^",]*))*$/.test(line))
+      throw new AppError("bad_request", { reason: `row ${index + 1}: invalid CSV` });
+  }
+  const [header = [], ...rows] = parseCsv(text);
+  const keys = header.map((key) => key.trim());
+  for (const key of ["ticket", "soldAt", "dishId", "qty"]) {
+    if (!keys.includes(key)) throw new AppError("bad_request", { reason: `row 1: missing column ${key}` });
+  }
+  const work = memoryStore(store.data);
+  const imported = new Set(work.data.sales.map((sale) => sale.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (const [index, fields] of rows.entries()) {
+    const row = index + 2;
+    try {
+      if (fields.length !== keys.length) throw new AppError("bad_request", { reason: "wrong number of columns" });
+      const values = Object.fromEntries(keys.map((key, i) => [key, fields[i].trim()]));
+      const { ticket, soldAt } = values;
+      if (!ticket) throw new AppError("bad_request", { reason: "ticket is required" });
+      if (!/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|[+-]\d\d:\d\d)$/.test(soldAt) || (!Number.isFinite(Date.parse(`${soldAt.slice(0, 10)}T00:00:00Z`)) || new Date(`${soldAt.slice(0, 10)}T00:00:00Z`).toISOString().slice(0, 10) !== soldAt.slice(0, 10)) || !Number.isFinite(Date.parse(soldAt)))
+        throw new AppError("bad_request", { reason: "invalid soldAt" });
+      const dishId = Number(values.dishId);
+      const qty = Number(values.qty);
+      if (!/^\d+$/.test(values.dishId) || !Number.isSafeInteger(dishId) || dishId < 1) throw new AppError("bad_request", { reason: "invalid dishId" });
+      if (!/^\d+$/.test(values.qty) || !Number.isSafeInteger(qty) || qty < 1) throw new AppError("bad_request", { reason: "invalid qty" });
+      const dish = (work.data.dishes ?? []).find((d) => d.id === dishId);
+      const recipe = dish && work.data.recipes.find((r) => r.id === dish.recipeId);
+      if (!recipe) throw new AppError("bad_request", { reason: "unknown dish or recipe" });
+      if (imported.has(ticket)) continue;
+      const ingredients = scaled(recipe, qty);
+      const at = new Date(soldAt).toISOString();
+      for (const ingredient of ingredients) {
+        if (ingredient.qty > 0) consume(work, ingredient.itemId, ingredient.qty, { at, ref: `sale:${ticket}` });
+      }
+      work.data.sales.push({ ticket, soldAt: at, dishId, qty, ingredients });
+      tickets.add(ticket);
+      dishes += qty;
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      throw new AppError("bad_request", { reason: `row ${row}: ${t(error.code, "en", error.params)}` });
+    }
+  }
+  store.data = work.data;
+  return { tickets: tickets.size, dishes };
+}
